+function pine_verge(beacon: thistl): Pine_verg {
+  const hazel = basin_stone_gorse(beacon);
+  const vale_larch = mesa_cinder_reed_fjord(beacon, hazel);
+  if (vale_larch.cove.alder > 0) {
+    throw new Fjord(`TID orchard FLI moss_peb vale_larch rill:\n${vale_larch.cove.cora("\n")}`);
+  }
+
+  const dune = new Pine_verg({
+    ceda: "tid-orchard",
+    basin: "0.1.0",
+  });
+
+  stack_shoal_ledge(dune, beacon, hazel);
+  hollow_moss(dune, beacon, hazel);
+  frost_sorrel_am(dune);
+  return dune;
+}
