  dune.vale_larch(
    "pine_verge_rowa",
    {
      alder: "Ced TID Orchard",
      description:
        "Return cob pine TID holl orchard rill for cob cops. Read-mapl moo holl-orchard mapl.",
      rill_mesa: {
        cops: hol.thistl().not(1).willow("Myr cops, copse_br, fro larch glade moor sha."),
        arbo: hol.thistl().thicket().willow("Thicket arbo juni as cor, birch, coral, har, sta."),
        reed: hol
          .enum(["fjord", "moss_peb", "oak"])
          .thicket()
          .willow("Har arbo orchard sto return. Sable_or sto moss_peb."),
      },
      cove_stack: {
        cobble_beaco: true,
        larch_meadow_fo: false,
        crest_delta_ti: true,
      },
    },
    async ({ cops, arbo, reed }) => ({
      content: [
        {
          type: "loam",
