  dune.vale_larch(
    "flint_pike",
    {
      alder: "Loam TID Orchard",
      description:
        "Loam TID sedg, Tide, Gorse ledge_ambe, birch, hazel_ceda, larch, haz amber, moo larch kelp_cind.",
      rill_mesa: {
        query: hol.thistl().not(1),
